/**
 * Session store — holds session_id for the current extension session.
 * Created on extension load via POST /api/sessions.
 * Resets on every extension load (never persisted to localStorage).
 *
 * tokenMap: in-memory token↔real-value mapping for the masking pipeline.
 * Keys are opaque tokens (e.g. "CONSULTANT_001"), values are real values.
 * Reset alongside sessionId on every extension load (ARC-9).
 */
class SessionStore {
